function showFidelity(){
 const preview=asset=>renderer.images[asset]?.src||'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(G.AVP_ASSETS[asset]||'');
 const rows=D.fidelityAudit,local=G.AVP_FIDELITY.props(game.s),labels={ACTIF:'Fonction exécutée',SCENE:'Visible / scène',LIEU:'Lieu représenté',DOCUMENT:'Documentaire seulement',ABSENT:'Absent du parcours',A_VERIFIER:'Référence à vérifier',HORS_CAMPAGNE:'Hors montage de référence'};
 openPanel('AVP · Référentiel de fidélité',`<p class="panel-intro">Atelier de vérification · contient la fin du récit. Le montage cinéma est la base ; Unrated, plans supprimés et raccords de jeu restent séparés. <strong>Une fiche ne prouve pas un objet jouable.</strong></p><div class="fidelity-tools"><label>Rechercher<input id="fidelity-search" placeholder="Nom, identifiant, propriétaire…" autocomplete="off"></label><label>Catégorie<select id="fidelity-category"><option value="">Toutes</option>${[...new Set(rows.map(x=>x.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>Présence réelle<select id="fidelity-presence"><option value="">Tous les états</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><p class="muted" id="fidelity-count" role="status"></p><details class="fidelity-local"><summary>Dans cette salle : ${esc(game.room.name)}</summary><p>${esc(game.room.referenceKind)}. ${esc(game.room.design)}</p><div class="fidelity-props">${local.map(p=>`<figure><img alt="${esc(p.asset)}" src="${esc(preview(p.asset))}"><figcaption>${esc(p.owner||'Décor')}<br><small>${esc(p.asset)}</small></figcaption></figure>`).join('')||'<p>Aucun nouveau accessoire de référence dans cette salle ; consulter aussi les objets hérités du codex.</p>'}</div><h3>Les accès</h3>${game.room.doors.map(d=>`<p><b>${esc(d.label)}</b> — ${esc(d.arch.label)}${d.levelDelta?' · niveau '+(d.levelDelta>0?'+':'')+d.levelDelta:''}.</p>`).join('')}</details><div id="fidelity-results" class="fidelity-results"></div><p class="muted">Les armes humaines restent aux agents de sécurité et les armes Yautja à leurs propriétaires. Pas de déblocage distant, de récompense ou de déplacement depuis ce registre. Les apparences restent des interprétations non certifiées 1:1.</p>`,'fidelity');
 function update(){const q=$('fidelity-search').value.trim().toLocaleLowerCase('fr'),cat=$('fidelity-category').value,status=$('fidelity-presence').value;const found=rows.filter(r=>(!cat||r.category===cat)&&(!status||r.presence===status)&&(!q||[r.id,r.name,r.owner,r.implementation].join(' ').toLocaleLowerCase('fr').includes(q)));
 $('fidelity-count').textContent=found.length+' / 250 références · leur statut décrit le code actuel, pas une promesse de contenu';
 $('fidelity-results').innerHTML=found.map(r=>`<article class="fidelity-record" data-id="${esc(r.id)}"><div class="fidelity-record-head">${r.asset&&G.AVP_ASSETS[r.asset]?`<img alt="${esc(r.name)} · version stylisée" src="${esc(preview(r.asset))}">`:''}<div><small>${esc(r.id)} · ${esc(r.category)}</small><h3>${esc(r.name)}</h3><span class="fidelity-tag ${r.presence.toLowerCase()}">${esc(labels[r.presence])}</span></div></div><p>${esc(r.implementation)}</p><p class="muted">${esc(r.owner)}${r.rooms.length?' · '+r.rooms.map(id=>esc(C.ROOMS.get(id)?.name||id)).join(' / '):''}</p><details><summary>Référence et périmètre</summary><p>${esc(r.sourceScope)}. ${esc(r.evidence)}</p><p class="muted">Le libellé original « ${esc(r.sourceClaim)} » vient du catalogue ; il n’est pas une validation indépendante par le jeu.</p></details></article>`).join('');
 }
 $('fidelity-search').oninput=update;$('fidelity-category').onchange=update;$('fidelity-presence').onchange=update;update();
}

function toTitle(){$('encounter-cue').hidden=true;$('evac-help').hidden=true;document.getElementById('playfield').classList.remove('is-hauling','evac-prompt-visible');save();playing=false;paused=false;epilogue=false;closePanel();$('title').hidden=false;$('shell').classList.add('title-state');$('cycle').hidden=true;$('notice').hidden=true;$('stealth-strip').hidden=true;$('terrain-help').hidden=true;$('threshold-help').hidden=true;$('party-strip').hidden=true;$('party-help').hidden=true;$('conversation').hidden=true;$('crossing-hud').hidden=true;document.getElementById('playfield').classList.remove('is-crossing');updateSlot();}
function showSeal(){const symbols=['◇','△','◉','╳'];openPanel('Le sceau des chasseurs',`<p class="seal-intro">Trois anneaux entourent le coffre. Le relief au-dessus indique leur ordre.</p><div class="seal-clue" aria-label="Ordre du relief : cercle, triangle, croix">◉ · △ · ╳</div><div class="seal-rings">${game.s.seal.rings.map((n,i)=>`<button data-ring="${i}" aria-label="Tourner l’anneau ${i+1}"><span>${symbols[n]}</span><small>Anneau ${i+1}</small></button>`).join('')}</div><p id="seal-message" role="status">Faire tourner les anneaux, puis vérifier le mécanisme.</p><div class="button-row"><button class="primary" id="check-seal">Vérifier le sceau</button><button id="leave-seal">S’éloigner</button></div>`,'seal');
 for(const b of document.querySelectorAll('[data-ring]'))b.onclick=()=>{const i=Number(b.dataset.ring);game.turnRing(i);b.querySelector('span').textContent=symbols[game.s.seal.rings[i]];};$('check-seal').onclick=()=>{if(game.unlockSeal()){closePanel();game.completeObjective();save();}else $('seal-message').textContent='La pierre résiste. Reprendre l’ordre gravé au-dessus du coffre.';};$('leave-seal').onclick=closePanel;}

function showBalance(){
 const o=D.operations.find(o=>o.id==='balance');if(!game.availableOperations.includes(o)||!game.near(o,88))return;
 openPanel('Les trois contrepoids',`<p class="seal-intro">La frise compte les crans de gauche à droite. La chaîne la plus longue porte le poids le plus bas.</p><div class="balance-clue" aria-label="Crans à régler : un, trois, deux"><span>Ⅰ</span><span>Ⅲ</span><span>Ⅱ</span></div><div class="weight-grid">${game.s.balance.map((n,i)=>`<section class="weight-column"><div class="weight-shaft"><i class="weight-chain"></i><div id="weight-${i}" class="weight-block" style="top:${18+n*29}px"><span>${i+1}</span></div></div><div class="weight-buttons"><button data-weight="${i}" data-delta="-1" aria-label="Monter le contrepoids ${i+1}">−</button><b id="weight-number-${i}">${n}</b><button data-weight="${i}" data-delta="1" aria-label="Descendre le contrepoids ${i+1}">+</button></div></section>`).join('')}</div><p id="weight-message" role="status">Alignez les trois contrepoids avant d’engager le verrou.</p><div class="button-row"><button id="check-weight" class="primary">Engager le verrou</button><button id="leave-weight">Revenir à la salle</button></div>`,'balance');
 for(const b of document.querySelectorAll('[data-weight]'))b.onclick=()=>{const i=Number(b.dataset.weight);if(game.turnWeight(i,Number(b.dataset.delta))){$('weight-number-'+i).textContent=game.s.balance[i];$('weight-'+i).style.top=18+game.s.balance[i]*29+'px';save();}};
 $('check-weight').onclick=()=>{if(game.s.balance.every((n,i)=>n===[1,3,2][i])&&game.doOperation(o)){closePanel();save();notify('Les contrepoids retiennent la dalle.');}else $('weight-message').textContent='Les chaînes ne sont pas alignées avec la frise : I · III · II.';};$('leave-weight').onclick=closePanel;
}
function showOperations(){if(!playing)return;
 const current=game.objective,required=D.operations.filter(o=>o.forFlag===current?.flag),extra=D.operations.filter(o=>!o.forFlag&&game.s.visited.includes(o.room)&&(!o.after||game.s.flags[o.after]));
 const card=o=>`<article class="task ${game.s.operations.includes(o.id)?'done':''}"><span class="task-dot" aria-hidden="true">${game.s.operations.includes(o.id)?'✓':'○'}</span><div><h3>${esc(o.title)}</h3><p>${esc(C.ROOMS.get(o.room).name)}</p><small>${game.s.operations.includes(o.id)?'Terminé.':esc(game.operationReason(o)?'D’abord : '+game.operationReason(o):'Rejoignez ce lieu et maintenez E sur le mécanisme.')}</small></div></article>`;
 openPanel('Ce qu’il reste à faire',`<div class="task-heading"><span class="eyebrow">ÉTAPE ${Math.min(19,game.s.chapter+1)} / 19</span><h3>${esc(current?.title||'Expédition terminée')}</h3><p>${esc(current?C.ROOMS.get(current.room).name:'Le carnet est complet.')}</p></div><div>${required.length?required.map(card).join(''):'<p>Rejoignez le prochain repère de l’expédition.</p>'}</div>${extra.length?'<h3 class="optional-title">En chemin</h3>'+extra.map(card).join(''):''}<div class="button-row"><button id="tasks-map">Carte des passages</button><button id="tasks-local">Plan de cette salle</button></div><p class="muted small">Les notes et les réserves trouvées en chemin ne sont jamais obligatoires pour terminer l’expédition.</p>`,'operations');
 $('tasks-map').onclick=showMap;$('tasks-local').onclick=showLocalMap;
}
function showLocalMap(){if(!playing)return;const r=game.room,main=game.guide;
 const color='#c1b889';let svg=`<svg xmlns="http://www.w3.org/2000/svg" class="local-plan" viewBox="0 0 ${r.width} 470" role="img" aria-label="Plan de ${esc(r.name)}. Les obstacles sont pleins, les passages sont cerclés."><rect x="35" y="90" width="${r.width-70}" height="280" fill="#18333e" stroke="#7a9691" stroke-width="3"/><path d="M35 230H${r.width-35}" stroke="#92a49344" stroke-width="2" stroke-dasharray="15 20"/>`;
 const y=v=>v+95;
 for(const b of r.solids)svg+=`<rect x="${b.x}" y="${y(b.y)}" width="${b.w}" height="${b.h}" fill="#607472" stroke="#adb69b" stroke-width="2"/>`;
 for(const b of game.slabs())svg+=`<rect x="${b.x}" y="${y(b.y)}" width="${b.w}" height="${b.h}" fill="${b.closed?'#b18562':'#b1856229'}" stroke="#d7b47a" stroke-width="3" stroke-dasharray="6 5"/>`;
 for(const d of r.doors){const py=y(game.isSide?144:d.y);svg+=`<circle cx="${d.x}" cy="${py}" r="18" fill="#12313d" stroke="${game.gate(d)?'#9c785b':'#a9c6b0'}" stroke-width="4"/><text x="${d.x}" y="${py+48}" text-anchor="middle" fill="#c8d8c6" font-size="23" font-family="system-ui">${esc(d.label.split(' · ').pop().slice(0,22))}</text>`;}
 for(const o of D.interactables.filter(o=>o.room===r.id)){const py=y(game.isSide?144:o.y);svg+=`<rect x="${o.x-9}" y="${py-9}" width="18" height="18" fill="${o.kind==='hide'?'#7fbfb5':game.s.opened.includes(o.id)||game.s.clues.includes(o.id)?'#47605c':'#c5b990'}" stroke="#ced6ba" stroke-width="2"/>`;}
 for(const o of game.availableOperations){svg+=`<path d="M${o.x} ${y(game.isSide?144:o.y)-13}l13 13-13 13-13-13Z" fill="${o.forFlag?color:'#87b8ae'}"/>`;}
 if(main?.room===r.id)svg+=`<circle cx="${main.x}" cy="${y(game.isSide?144:main.y)}" r="25" fill="none" stroke="#e6cd91" stroke-width="3"/>`;
 svg+=`<circle cx="${game.s.player.x}" cy="${y(game.s.player.y)}" r="12" fill="#f2e1ad"/><text x="${game.s.player.x}" y="${y(game.s.player.y)-26}" text-anchor="middle" font-size="25" font-family="system-ui" fill="#f2e1ad">LEX</text></svg>`;
 openPanel(r.name,`<p>${esc(r.mood)}</p><div class="local-scroll">${svg}</div><div class="plan-legend"><span>● Lex</span><span>◇ Actions</span><span>▧ Obstacles</span><span>▱ Dalles mobiles</span><span>□ Objets / niches</span></div><p class="small muted">${game.isSide?'Passage latéral : les seuils sont accessibles sur l’axe central.':'Les obstacles peuvent être contournés en changeant de profondeur.'} La carte n’offre aucun déplacement instantané.</p><div class="passage-list">${r.doors.map(d=>`<p><b>${esc(d.label)}</b><span>${esc(game.gate(d)||'Passage libre')}</span></p>`).join('')}</div><div class="button-row"><button id="local-global">Carte de l’expédition</button><button id="local-tasks">Actions en cours</button></div>`,'localmap');
 $('local-global').onclick=showMap;$('local-tasks').onclick=showOperations;
}


function showTerrain(){
 const known=D.devices.filter(d=>game.s.visited.includes(d.room));
 openPanel('Le terrain, pas seulement un décor',`<p class="terrain-lead">T maintenu actionne l’équipement proche. Son effet continue sans ouvrir ce carnet. Les actions ici sont originales à cette adaptation.</p><div class="terrain-guide"><section><strong>Éclairer</strong><p>La frontale et les projecteurs sont indépendants. L’éclairage au sol rend les silhouettes plus faciles à repérer, sans traverser un obstacle.</p></section><section><strong>Détourner</strong><p>Les chaînes et la radio partent après 2,6 secondes. Le bruit attire vers leur position. Le réarmement empêche de relancer le leurre immédiatement.</p></section><section><strong>Masquer</strong><p>La condensation dure sept secondes. Elle coupe la vue, pas les tirs, les coups ni les sons.</p></section></div><h3>Équipements dans les lieux visités · ${known.length} / ${D.devices.length}</h3><div class="terrain-cards">${known.map(d=>{const st=game.deviceState(d),asset=d.kind==='lamp'?'utility-lamp':d.kind==='radio'?'utility-radio':d.kind==='mist'?'utility-valve':'utility-chain';return `<article class="terrain-card"><img alt="" src="data:image/svg+xml;charset=utf-8,${encodeURIComponent(G.AVP_ASSETS[asset])}"><div><span class="eyebrow">${esc(C.ROOMS.get(d.room).name)}</span><h4>${esc(d.title)}</h4><p>${esc(d.text)}</p><small>${esc(game.deviceLabel(d))}</small></div></article>`;}).join('')||'<p>Explorer les lieux pour relever leurs équipements.</p>'}</div><h3>Le bruit sous vos pieds</h3><div class="terrain-materials">${Object.entries(D.materials).map(([id,m])=>`<article><b>${esc(m.name)}</b><p>${id==='resin'?'Pas amortis ; résine lente pour Lex et Scar.':id==='water'?'Pas audibles et déplacements ralentis.':id==='metal'||id==='shards'?'Le bruit porte loin. Approcher accroupi.':id==='snow'?'Les pas portent moins loin.':'Le niveau de référence pour les dalles.'}</p></article>`).join('')}</div>${game.s.visited.includes('icebattle')?'<h3>La ligne de traction</h3><p>Préparer le lance-piton avec E, puis lancer avec T. Viser sur le même plan pendant la reprise de la Reine. Un tir manqué revient après 2,2 secondes. Une fois la ligne accrochée, attirer la Reine dans la zone indiquée et libérer le butoir avec E.</p>':''}<p class="muted">Aucun bouton de cette page ne manœuvre un équipement à distance. Carte, carnets et pause suspendent aussi les délais de réarmement.</p>`,'terrain');
}

function showOptions(){openPanel('Réglages et commandes',`<div class="option-row"><div>Présentation<p class="muted">Le même parcours, sans changer la progression.</p></div><select id="view-setting"><option value="hybrid">Vues hybrides</option><option value="classic">2D latérale</option></select></div><div class="option-row"><div>Ambiance sonore<p class="muted">Sons synthétisés. Aucun dialogue enregistré.</p></div><input id="volume-setting" type="range" min="0" max="100" step="5" aria-label="Volume"></div><label class="option-row"><div>Réduire les mouvements<p class="muted">Atténue les particules, les oscillations et les éclats.</p></div><input id="motion-setting" type="checkbox"></label><div class="commands">${[['ZQSD / ↑↓←→','Se déplacer ; avant / arrière dans les grandes salles'],['E / Entrée','Interagir ; maintenir près d’un objectif'],['Clic / J','Frapper avec le piolet ou la lance'],['Espace','Esquiver'],['Maj','Courir'],['C','Avancer accroupi'],['Clic droit / R','Garder avec le bouclier, après l’alliance'],['F','Lancer une fusée éclairante'],['H','Utiliser une trousse pour Lex'],['I maintenu','Secourir / soigner un compagnon ou utiliser la halte proche'],['Maj + I','Saisir un compagnon à terre (0,85 s) ; I pour déposer'],['M / Tab','Carte / carnet'],['P / N','Actions en cours / plan de la salle'],['V maintenu','Fermer / rouvrir un vantail proche'],['X maintenu','Écouter près d’un seuil, sans arrêter le monde'],['L','Allumer / éteindre la lampe'],['B','Dossiers et observations de terrain'],['E près d’une niche','Se cacher / ressortir ; attention aux témoins'],['G','Scar : suivre / garder la position'],['T maintenu','Actionner l’équipement proche ; T bref lance le piton au final'],['K','Consulter les équipements et les sols'],['U','Parler à proximité / maintenir pour un relevé de Sebastian'],['1 / 2','Choisir une réponse pendant un échange'],['O','Compagnons, ordres et échanges conservés'],['F6','Changer de présentation'],['Échap','Ouvrir ou fermer la pause']].map(([k,t])=>`<div><kbd>${k}</kbd><span>${t}</span></div>`).join('')}</div><p class="muted">Les portes se rejoignent à pied. La carte ne téléporte pas Lex. Les symboles dorés au sol signalent les objectifs ; les petits carrés signalent les notes.</p><p class="small muted">Version ${D.version} · Adaptation non officielle. Les textes de cette campagne sont originaux.</p>`,'options');
 $('view-setting').value=playing?game.s.mode:settings.mode;$('view-setting').disabled=!!(playing&&game.s.evacuation.haul);$('volume-setting').value=String(settings.volume*100);$('motion-setting').checked=settings.reduced;
 $('view-setting').onchange=e=>{settings.mode=e.target.value;if(playing){game.setMode(settings.mode);settings.mode=game.s.mode;e.target.value=settings.mode;}persistSettings();save();};$('volume-setting').oninput=e=>{settings.volume=Number(e.target.value)/100;audio.wake();persistSettings();};$('motion-setting').onchange=e=>{settings.reduced=e.target.checked;persistSettings();};
}
let mapRegion=null,mapZoom=.72;
function showMap(region=null){if(!playing)return;
 mapRegion=typeof region==='string'?region:(G.AVP_MAP.regionOf[game.s.room]||'ship');
 const model=G.AVP_MAP.build(game,mapRegion),s=game.s,visited=model.visited;
 openPanel('Les passages connus',`<div class="atlas-tools"><div class="atlas-tabs" role="group" aria-label="Région de la carte">${Object.entries(G.AVP_MAP.groups).map(([id,r])=>`<button data-map-region="${id}" aria-pressed="${id===mapRegion}">${esc(r.label)}</button>`).join('')}</div><div class="atlas-zoom"><button id="map-less" aria-label="Réduire la carte">−</button><span id="map-zoom-label"></span><button id="map-more" aria-label="Agrandir la carte">+</button><button id="map-center">Lex</button></div></div><div class="map-layout atlas-layout"><div class="map-scroll hunt-map" style="--map-width:${model.width*mapZoom}px">${model.svg}</div><aside class="map-note"><span class="progress-title">RELEVÉ DES ÉTAGES</span><div id="map-detail"></div><p class="map-memory">Les vantaux affichent leur dernier état constaté. Une porte hors de portée n’est pas un capteur à distance.</p><button id="map-history">Les dernières traces</button></aside></div><div class="plan-legend"><span>● Lex</span><span>□ Vantail</span><span>┄ Cycle</span><span>↑↓ Étage</span></div><p class="muted small">Schéma de connexions du jeu, pas un relevé métrique du film. Les lieux non parcourus restent « Passage aperçu ». Aucun déplacement rapide.</p>`,'map');
 const choose=node=>{const r=C.ROOMS.get(node.dataset.room);if(!r)return;const route=game.knownRoute(r.id),leaves=r.doors.filter(d=>game.portalFor(d));
  $('map-detail').innerHTML=`<h3>${esc(visited.has(r.id)?r.name:'Passage aperçu')}</h3><p>${esc(visited.has(r.id)?r.mood:'Le relevé s’arrête au seuil.')}</p><p class="small">${r.id===s.room?'Vous êtes ici.':route.length?`${route.length-1} passage(s) à rejoindre à pied.`:'Aucun itinéraire connu accessible.'}</p>${visited.has(r.id)?leaves.map(d=>{const p=game.portalFor(d),v=s.portalMemory[p.id],label={open:'Ouvert',closed:'Fermé',closing:'En fermeture',broken:'Brisé'}[v?.status]||'Non observé';return `<p class="portal-memory"><b>${esc(p.title)}</b><span>${label}${v?' · dernier constat':''}</span></p>`;}).join(''):''}<button id="mark-route">Marquer ce lieu</button><button id="clear-route">Effacer le repère</button>`;
  $('mark-route').onclick=()=>{if(game.markRoute(r.id)){save();notify('Repère ajouté. Rejoignez les seuils à pied.');closePanel();}};
  $('clear-route').onclick=()=>{game.markRoute(null);save();closePanel();};
 };
 $('panel-body').querySelectorAll('.map-node').forEach(n=>{n.onclick=()=>choose(n);n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(n);}};});
 for(const b of document.querySelectorAll('[data-map-region]'))b.onclick=()=>showMap(b.dataset.mapRegion);
 const zoom=delta=>{mapZoom=C.clamp(mapZoom+delta,.45,1.6);document.querySelector('.hunt-map').style.setProperty('--map-width',model.width*mapZoom+'px');$('map-zoom-label').textContent=Math.round(mapZoom*100)+'%';};zoom(0);
 $('map-less').onclick=()=>zoom(-.15);$('map-more').onclick=()=>zoom(.15);
 $('map-center').onclick=()=>{const reg=G.AVP_MAP.regionOf[s.room];if(mapRegion!==reg)showMap(reg);else $('panel-body').querySelector(`[data-room="${s.room}"]`)?.scrollIntoView({block:'center',inline:'center'});};
 $('map-history').onclick=showHuntJournal;
 const active=$('panel-body').querySelector(`[data-room="${s.room}"]`)||$('panel-body').querySelector('.map-node');
 if(active){choose(active);setTimeout(()=>active.scrollIntoView({block:'nearest',inline:'center'}),10);}else $('map-detail').innerHTML='<p>Aucun passage relevé dans cette région.</p>';
}
function showHuntJournal(){if(!playing)return;
 openPanel('Les dernières traces',`<p class="muted">Ce que Lex a vu ou entendu. Ce carnet ne révèle ni les positions ennemies ni les pièces inexplorées.</p><div class="hunt-journal">${game.s.huntJournal.length?[...game.s.huntJournal].reverse().map(e=>`<article><span>${clock(e.at)} · ${esc(C.ROOMS.get(e.room).name)}</span><p>${esc(G.AVP_HUNT.journalText[e.code])}</p></article>`).join(''):'<p>Aucun franchissement ni impact observé pour le moment.</p>'}</div><div class="button-row"><button id="hunt-map">Revenir à la carte</button><button id="hunt-resume">Reprendre l’expédition</button></div>`,'hunt');
 $('hunt-map').onclick=()=>showMap();$('hunt-resume').onclick=closePanel;
}
function showBehaviors(){if(!playing)return;
 const s=game.s.encounter,known=s.seen,labels={pounce:'Le bond du facehugger',tail:'Le coup de queue',duct:'Les passages de la créature'};
 const cards=Object.entries(labels).map(([k,label])=>`<article class="behavior-card"><span class="category">${known.includes(k)?'Observé':'À observer'}</span><h3>${known.includes(k)?esc(label):'Un comportement encore inconnu'}</h3><p>${known.includes(k)?esc(D.encounterNotes.find(n=>n.unlockBehavior===k).text):'Approcher prudemment. Ce carnet ne dévoile pas les positions des créatures.'}</p></article>`).join('');
 const openings=D.enemyDucts.map(d=>`<article class="behavior-duct"><h3>${s.openings.includes(d.id)?esc(d.title):'Une ouverture à découvrir'}</h3><p>${s.openings.includes(d.id)?esc(C.ROOMS.get(d.room).name):'Lieu inconnu'}</p></article>`).join('');
 const codes={pounce:'Bond préparé',tail:'Queue armée','duct-enter':'Entrée dans un conduit','duct-exit':'Sortie d’un conduit',interrupted:'Mouvement interrompu'};
 openPanel('Les angles morts',`<p class="behavior-lead">Observer, interrompre, s’écarter. Les déplacements, la frappe, la garde et l’esquive habituels restent vos réponses.</p><div class="behavior-cards">${cards}</div><h3>Ouvertures repérées</h3><p class="small muted">Un conduit reste dans une seule salle. Il ne crée pas de renfort et ne répare aucune blessure. Une sortie occupée retarde la créature.</p><div class="behavior-cards">${openings}</div><h3>Derniers mouvements observés</h3><div class="behavior-records">${s.journal.length?s.journal.slice(-8).reverse().map(j=>`<p><b>${esc(codes[j.code])}</b><span>${esc(C.ROOMS.get(j.room).name)}</span></p>`).join(''):'<p>Aucune observation encore consignée.</p>'}</div><button id="behaviors-codex">Notices détaillées du carnet</button>`,'behaviors');$('behaviors-codex').onclick=showCodex;
}
function syncEncounterUI(){const panel=$('encounter-cue');if(!panel)return;const cues=playing&&!paused&&!epilogue?game.encounterAlerts():[];panel.hidden=!cues.length;
 if(cues.length){const cue=cues[0],label=cue.text+(cues.length>1?' · '+cues.length+' alertes':'');if(panel.querySelector('strong').textContent!==label)panel.querySelector('strong').textContent=label;panel.querySelector('span').textContent=cue.hint;panel.dataset.kind=cue.kind;}
}

function showCodex(){if(!playing)return;const unlocked=game.unlockedCodex(),logs=D.rooms.flatMap(r=>r.collectibles).filter(l=>game.s.logs.includes(l.id)).map(l=>({title:l.title,text:l.text,category:'Notes'}));const fieldNotes=D.operations.filter(o=>['note','map'].includes(o.reward)&&game.s.operations.includes(o.id)).map(o=>({title:o.title,text:o.text,category:'Notes'}));const clues=D.interactables.filter(o=>o.kind==='clue'&&game.s.clues.includes(o.id)).map(o=>({title:o.title,text:o.text,category:'Notes'}));const entries=[...unlocked,...logs,...fieldNotes,...clues];
 openPanel('Le carnet de Lex',`<div class="codex-toolbar"><input id="codex-search" placeholder="Rechercher un lieu, une rencontre, un indice…" aria-label="Rechercher dans le carnet"><select id="codex-filter" aria-label="Catégorie"><option value="">Toutes les rubriques</option>${['Lieux','Rencontres','Équipement','Terrain','Notes','Survie · Les seuils','Compagnons','Franchissements','Secours','Évacuation','Comportements'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="codex-count">${unlocked.length} / ${D.codex.length} entrées découvertes · ${logs.length+fieldNotes.length+clues.length} notes et relevés recueillis</div><div class="codex-list" id="codex-list"></div>`,'codex');
 const render=()=>{const q=$('codex-search').value.toLocaleLowerCase('fr'),cat=$('codex-filter').value,found=entries.filter(e=>(!cat||e.category===cat)&&(`${e.title} ${e.text}`.toLocaleLowerCase('fr').includes(q)));$('codex-list').innerHTML=found.length?found.map(e=>`<article class="codex-entry"><span class="category">${esc(e.category)}</span><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p></article>`).join(''):'<div class="empty">Rien n’est encore inscrit dans cette rubrique.</div>';};$('codex-search').oninput=render;$('codex-filter').onchange=render;render();
}

function showInvestigations(){if(!playing)return;
 const known=new Set(game.s.visited);for(const rid of game.s.visited)for(const d of C.ROOMS.get(rid)?.doors||[])known.add(d.to);
 const cards=D.investigations.map(d=>{const count=d.clues.filter(id=>game.s.clues.includes(id)).length;
  return `<article class="investigation ${count===d.clues.length?'complete':''}"><div class="investigation-top"><span class="eyebrow">DOSSIER DE TERRAIN</span><b>${count} / ${d.clues.length}</b></div><h3>${esc(d.title)}</h3><div class="progress-line"><i style="width:${100*count/d.clues.length}%"></i></div>${d.clues.map(id=>{const o=D.interactables.find(x=>x.id===id),found=game.s.clues.includes(id);return `<section class="clue-card"><span>${found?'✓':'○'}</span><div><h4>${esc(found?o.title:known.has(o.room)?'Relevé à découvrir':'Trace non localisée')}</h4><p>${esc(found?o.text:known.has(o.room)?C.ROOMS.get(o.room).name:'Poursuivez l’exploration des embranchements.')}</p>${!found&&known.has(o.room)?`<button data-clue-route="${o.room}">Marquer le lieu</button>`:''}</div></section>`;}).join('')}${count===d.clues.length?`<p class="dossier-result">${esc(d.text)}</p>`:''}</article>`;
 }).join('');
 openPanel('Les traces des vivants',`<p class="muted">Recouper les indices, retrouver les passages et comprendre ce que la station a laissé derrière elle.</p><div class="field-summary"><b>${game.s.clues.length} / 9 observations</b><span>${game.s.opened.length} / 10 contenants fouillés</span><span>${game.s.shortcuts.length} / 2 retours déverrouillés</span></div><div class="investigation-grid">${cards}</div>`,'investigations');
 for(const b of document.querySelectorAll('[data-clue-route]'))b.onclick=()=>{if(game.markRoute(b.dataset.clueRoute)){save();closePanel();notify('Repère inscrit sur la carte.');}};
}

function syncCrossingUI(){
 const v=playing&&!epilogue?game.crossingView():null,box=$('crossing-hud');box.hidden=!v;$('playfield').classList.toggle('is-crossing',!!v);document.querySelector('[data-key=crouch]').textContent=v?'Tenir':'Accroupie';document.querySelector('[data-key=run]').textContent=v?'Accélérer':'Courir';if(!v)return;
 $('crossing-title').textContent=v.title;$('crossing-destination').textContent='Vers '+v.to;
 const progress=Math.round(v.progress*100),grip=Math.ceil(v.grip);
 $('crossing-percent').textContent=progress+' %';$('crossing-grip-number').textContent=grip+' %';
 for(const [id,val] of [['crossing-progress',progress],['crossing-grip',grip]]){const el=$(id);el.firstElementChild.style.width=val+'%';el.setAttribute('aria-valuenow',String(val));}
 $('crossing-alert').textContent=v.alert.toUpperCase();box.dataset.danger=String(!!v.hazard||grip<25);
 const forward=v.axis==='y'?(v.direction<0?'↑':'↓'):(v.direction<0?'←':'→'),back=v.axis==='y'?(v.direction<0?'↓':'↑'):(v.direction<0?'→':'←');
 $('crossing-controls').innerHTML=`<kbd>${forward}</kbd> Avancer · <kbd>${back}</kbd> Revenir<br><kbd>${v.axis==='y'?'← →':'↑ ↓'}</kbd> Se décaler · <kbd>C</kbd> Tenir<br><kbd>Maj</kbd> Accélérer · <kbd>E</kbd> Annuler au départ`;
 $('room-label').textContent='FRANCHISSEMENT · '+v.to;$('objective-label').textContent=v.title;$('prompt').innerHTML=`<kbd>${forward}</kbd> Avancer · <kbd>C</kbd> Assurer la prise · <kbd>Échap</kbd> Pause`;
 for(const id of ['party-strip','party-help','terrain-help','threshold-help','stealth-strip','conversation'])$(id).hidden=true;
}
function showCrossings(){if(!playing)return;
 const current=game.s.traversal;
 const cards=D.traversals.map(t=>{const known=[t.a,t.b].some(d=>game.s.visited.includes(d.split('--')[0])),r=game.s.crossingRecords?.[t.id];
 if(!known)return `<article class="crossing-card unknown"><span class="eyebrow">PASSAGE NON RELEVÉ</span><h3>Une ligne à découvrir</h3><p>Le carnet se complète en visitant les lieux.</p></article>`;
 return `<article class="crossing-card ${r?'completed':''}"><span class="eyebrow">${esc(t.kind)} · ${r?'FRANCHI':'APERÇU'}</span><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p><div class="crossing-endpoints">${esc(C.ROOMS.get(t.a.split('--')[0]).name)} ↔ ${esc(C.ROOMS.get(t.b.split('--')[0]).name)}</div><p class="small">${r?r.count+' franchissement(s) achevé(s) · '+r.directions.length+' sens parcouru(s)':'E engage le passage depuis l’un de ses deux accès.'}</p></article>`;}).join('');
 openPanel('Tenir la ligne',`<p class="crossing-intro">Rejoindre le seuil, s’engager, choisir son allure. Les flèches suivent l’axe de la traversée ; les flèches perpendiculaires décalent le corps. C assure la prise. Revenir jusqu’au départ annule le trajet.</p>${current?'<p class="crossing-paused">Traversée en pause · '+esc(G.AVP_TRAVERSAL.defs.get(current.id).title)+' · '+Math.round(current.progress*100)+' %. Reprendre rend les commandes sans déplacement automatique.</p>':''}<div class="crossing-grid">${cards}</div><h3>Ne pas confondre prise et protection</h3><p>Accélérer fatigue rapidement. Une prise vide provoque un glissement et une blessure. C récupère la prise et réduit les impacts, sans rendre invulnérable. Les alarmes visuelles restent présentes sans audio.</p><h3>Le groupe suit le même lien</h3><p>Un compagnon rejoint le seuil à pied puis traverse en temps simulé. Son arrivée reste liée à la face réciproque. Il ne s’agit pas d’une téléportation de regroupement.</p><p class="muted small">Séquences contraintes originales pour le jeu. Les six volumes sont distincts des sols des pièces ; les ennemis restent dans celles-ci. Ce système n’est ni une escalade libre ni une simulation physique de corde. Ce carnet suspend le monde.</p>`,'crossings');
}
$('crossing-guide-button').onclick=showCrossings;

function partyPortrait(id){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(G.AVP_ASSETS[id]||G.AVP_ASSETS.lex);}
let talkUIKey='';
function syncPartyUI(){
 const strip=$('party-strip'),help=$('party-help'),panel=$('conversation');
 strip.hidden=!playing||epilogue||!!game.s.scene;
 strip.innerHTML=D.companions.filter(d=>game.s.party?.[d.id]).map(d=>`<span><b>${esc(d.name)}</b>${esc(game.partyStatus(d.id))}</span>`).join('');
 const study=game.nearestStudy(),talk=game.nearestConversation(),v=playing&&!paused?game.conversationView():null;
 help.hidden=!playing||epilogue||!!game.s.scene||!!v||(!study&&!talk);
 help.textContent=study?`U maintenu · ${study.title}${game._studyTarget?' · '+(game.studyStatus(study)||Math.min(100,Math.floor((game._studyHold||0)/study.hold*100))+' %'):''}`:talk?'U · Parler à '+talk.name:'';
 panel.hidden=!v;if(!v){talkUIKey='';return;}
 const key=[v.id,v.stage,v.index,v.choice].join(':');if(key===talkUIKey)return;talkUIKey=key;
 panel.innerHTML=`<img src="${partyPortrait(v.actor)}" alt=""><div><span class="talk-meta">${esc(v.title)} · ÉCHANGE SUR LE TERRAIN</span><h3>${esc(v.speaker)}</h3><p>${esc(v.text)}</p>${v.hint?`<p class="talk-hint">${esc(v.hint)}</p>`:''}<div class="talk-buttons">${v.stage==='choice'?v.choices.map((c,i)=>`<button data-talk-choice="${i}"><kbd>${i+1}</kbd> ${esc(c)}</button>`).join(''):`<button id="talk-next" class="primary">${v.stage==='reply'?'Consigner et repartir':'Poursuivre'} <span>U</span></button>`}<button id="talk-cancel" class="text-button">Interrompre</button></div><div class="talk-live">LE TEMPS CONTINUE · Se déplacer ou l’approche d’un danger interrompt l’échange.</div></div>`;
 if($('talk-next'))$('talk-next').onclick=()=>{game.advanceConversation();syncPartyUI();};
 $('talk-cancel').onclick=()=>{game.cancelConversation(false);syncPartyUI();$('game').focus();};
 for(const b of panel.querySelectorAll('[data-talk-choice]'))b.onclick=()=>{game.advanceConversation(Number(b.dataset.talkChoice));syncPartyUI();};
}
function showParty(){
 if(!playing)return;
 const cards=D.companions.map(d=>{const v=game.s.party?.[d.id],known=!!game.s.flags[d.start]||game.s.visited.includes(d.id==='scar'?'hunter':'forecourt');
 if(!known)return `<article class="party-card"><div></div><div><h3>Une présence à rencontrer</h3><p>Le carnet se complète au fil de l’expédition.</p></div></article>`;
 return `<article class="party-card"><img src="${partyPortrait(d.asset)}" alt="${esc(d.name)}"><div><span class="eyebrow">${esc(d.role)}</span><h3>${esc(d.name)}</h3><p>${esc(v?game.partyStatus(d.id):'Son rôle dans cette étape est terminé.')}</p>${v?`<p>${esc(C.ROOMS.get(v.room).name)}${d.id==='scar'?' · Énergie '+Math.floor(game.s.ally.energy)+' %':''}</p><div class="button-row"><button data-party-id="${d.id}" data-command="follow" aria-pressed="${v.order==='follow'}">Regrouper</button><button data-party-id="${d.id}" data-command="hold" aria-pressed="${v.order==='hold'}" ${v.room!==game.s.room?'disabled':''}>Garder ici</button>${d.id==='scar'?`<button data-party-id="scar" data-command="support" aria-pressed="${v.stance==='support'}">Soutien</button><button data-party-id="scar" data-command="silent" aria-pressed="${v.stance==='silent'}">Discret</button>`:''}</div>`:''}</div></article>`;
 }).join('');
 const studies=D.studies.map(s=>{const done=game.s.studies.includes(s.id),known=game.s.visited.includes(s.room);return `<article class="study-card ${done?'done':''}"><h4>${known||done?esc(s.title):'Support encore inconnu'}</h4><p>${done?esc(s.text):game.s.flags.weyland?'Ce relevé n’a pas été effectué avant le départ de Sebastian.':known?'Rejoindre le support avec Sebastian avant son départ. U maintenu effectue le relevé.':'Explorer la pyramide avec Sebastian.'}</p><span class="small">${done?'RELEVÉ CONSERVÉ':game.s.flags.weyland?'CE PARCOURS DE RELEVÉ EST TERMINÉ':known?esc(C.ROOMS.get(s.room).name):'NON LOCALISÉ'}</span></article>`;}).join('');
 const records=D.encounters.filter(t=>game.s.conversations[t.id]).map(t=>{const choice=game.s.conversations[t.id].choice,ch=t.choices[choice];return `<details class="talk-record"><summary>${esc(t.title)} · ${esc(t.name)}</summary>${t.lines.map(l=>`<p><b>${esc(l[0])}</b> — ${esc(l[1])}</p>`).join('')}<p><b>Lex</b> — ${esc(ch.label)}</p><p>${esc(ch.reply)}</p><p class="muted">${esc(ch.hint)}</p></details>`;}).join('');
 openPanel('Ne pas rester seule',`<div class="team-guide"><b>O · Carnet des compagnons</b><span>U · Échange ou relevé à proximité</span><span>G · Suivre / garder avec Scar</span></div><p class="muted">Les ordres prennent effet à la reprise. Aucun regroupement ne déplace instantanément un compagnon. Une grille fermée peut le bloquer.</p><div class="party-grid">${cards}</div><div class="button-row"><button id="party-rescue">Blessures, secours et haltes</button><button id="party-evacuation">Évacuer un blessé</button></div><h3>Les relevés de Sebastian · ${game.s.studies.length} / 4</h3><div class="study-grid">${studies}</div><h3>Échanges conservés · ${Object.keys(game.s.conversations).length} / ${D.encounters.length}</h3>${records||'<p class="party-empty">Approchez un personnage et appuyez sur U. Les échanges terminés sont transcrits ici.</p>'}<p class="talk-log-note">Dialogues et relevés originaux pour cette adaptation. Les choix donnent un point de vue ou un ordre ; ils ne réécrivent pas les destins du récit. Les compagnons peuvent être blessés ou mis à terre. Le secours ne change pas les destins scénarisés du récit.</p>`,'party');
 $('party-rescue').onclick=showRescue;$('party-evacuation').onclick=showEvacuation;for(const b of document.querySelectorAll('[data-party-id]')){if(game.s.traversal||game.companionDown(b.dataset.partyId))b.disabled=true;b.onclick=()=>{game.orderCompanion(b.dataset.partyId,b.dataset.command);save();showParty();};}if(game.s.traversal){const p=document.createElement('p');p.className='crossing-paused';p.textContent='Terminer le franchissement pour donner un nouvel ordre.';$('panel-body').prepend(p);}
}


function syncRescueUI(){
 const box=$('aid-help'),a=playing&&!paused&&!epilogue?game.nearestAid():null;
 box.hidden=!a||!!game.s.scene||!!game.s.traversal;$('playfield').classList.toggle('care-prompt-visible',!box.hidden);
 if(!a)return;
 const pending=game._aid,progress=pending&&pending.id===a.id?Math.floor(pending.progress/pending.hold*100):0;
 box.classList.toggle('is-active',progress>0);
 box.innerHTML=`<span class="aid-kicker">${a.kind==='revive'?'SECOURS SUR PLACE':a.kind==='treat'?'PARTAGER UNE TROUSSE':'HALTE DE SOINS'}</span><b><kbd>I</kbd> ${esc(a.label)}</b><span>${a.reason?esc(a.reason):progress?`Garder I · ${progress} % · Le temps continue`:a.kind==='revive'?'Maintenir 3,8 s · Aucun consommable':a.kind==='treat'?'Maintenir 2,6 s · Une trousse à la réussite':'Maintenir 4,2 s · Un seul lot pour cette halte'}</span>${progress?`<div class="aid-track" role="progressbar" aria-label="Progression du secours" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><i style="width:${progress}%"></i></div>`:''}`;
}
function showRescue(){
 if(!playing)return;
 const state=game.s.rescue, active=D.companions.filter(d=>game.s.party?.[d.id]);
 const cards=active.map(d=>{const v=game.companionVital(d.id),rule=D.rescueRules[d.id],local=game.s.party[d.id].room===game.s.room;
  return `<article class="aid-person ${v.hp===0?'down':''}"><img src="${partyPortrait(d.asset)}" alt="${esc(d.name)}"><div><span class="eyebrow">${v.hp===0?'À TERRE':v.hp<rule.woundBelow?'BLESSURE CRITIQUE':'COMPAGNON'}</span><h3>${esc(d.name)}</h3><b>${Math.ceil(v.hp)} / ${rule.maxHp}</b><div class="aid-health" role="progressbar" aria-label="Santé de ${esc(d.name)}" aria-valuemin="0" aria-valuemax="${rule.maxHp}" aria-valuenow="${Math.ceil(v.hp)}"><i style="width:${v.hp/rule.maxHp*100}%"></i></div><p>${esc(C.ROOMS.get(game.s.party[d.id].room).name)}</p><p>${v.hp===0?'Le rejoindre à pied et maintenir I pour le relever.':v.hp<rule.maxHp?'Une trousse partagée avec I restaure jusqu’à 54 points.':'Aucun soin nécessaire.'}${local?'':' Aucun soin à distance.'}</p></div></article>`;
 }).join('');
 const stations=D.careStations.map(st=>{const known=game.s.visited.includes(st.room),used=state.usedStations.includes(st.id);return `<article class="aid-station ${used?'spent':''}"><span class="eyebrow">${known?used?'RÉSERVE ÉPUISÉE':'UN LOT DISPONIBLE':'NON LOCALISÉE'}</span><h3>${known?esc(st.title):'Une halte à découvrir'}</h3><p>${known?esc(st.description):'Le carnet ne dévoile pas son emplacement avant la visite de la pièce.'}</p>${known?`<p class="small">${esc(C.ROOMS.get(st.room).name)}</p><button data-care-route="${st.room}">Marquer le trajet à pied</button>`:''}</article>`;}).join('');
 const log=state.journal.slice(-12).reverse().map(e=>{const name=D.companions.find(d=>d.id===e.id)?.name||D.careStations.find(d=>d.id===e.id)?.title||'';return `<li><time>${clock(e.at)}</time><span>${esc(name)} · ${({down:'à terre',raised:'relevé sur place',treated:'une trousse partagée',station:'réserve utilisée'})[e.code]}</span></li>`;}).join('');
 openPanel('Personne derrière la grille',`<p class="aid-lead">Secourir n’arrête pas la chasse.</p><div class="aid-guide"><p><kbd>I</kbd> À terre : relever gratuitement en 3,8 s, avec santé partielle.</p><p><kbd>I</kbd> Debout et blessé : partager une trousse en 2,6 s.</p><p><kbd>H</kbd> Soigner Lex. <kbd>O</kbd> Retrouver le carnet des ordres.</p></div><p class="muted">Se déplacer, combattre ou subir un coup interrompt le soin sans consommer la trousse. Le soin partiel ne survit pas à la pause. Il n’existe ni hémorragie fatale ni résurrection : la mise à terre est une incapacité temporaire.</p><div class="aid-grid">${cards||'<p>Aucun compagnon actif à cette étape.</p>'}</div><h3>Quatre haltes, quatre réserves</h3><p class="muted">Au calme seulement : jusqu’à 60 points pour Lex et 65 pour les compagnons debout à proximité. Un lot par halte, sans recharge à la revisite. Les haltes ne sont pas des déplacements rapides ni des commandes de soin à distance.</p><div class="aid-grid">${stations}</div><h3>Secours consignés</h3><div class="aid-stat"><span>${state.stats.rescues} secours</span><span>${state.stats.treatments} trousses partagées</span><span>${state.usedStations.length} / 4 haltes utilisées</span></div><ol class="care-log">${log||'<li>Aucune intervention consignée.</li>'}</ol><div class="button-row"><button id="rescue-orders">Compagnons et ordres</button><button id="rescue-evacuation">Déplacer le blessé avant de le relever</button></div>`,'rescue');
 $('rescue-orders').onclick=showParty;$('rescue-evacuation').onclick=showEvacuation;
 for(const b of document.querySelectorAll('[data-care-route]'))b.onclick=()=>{if(game.markRoute(b.dataset.careRoute)){save();closePanel();notify('Halte marquée. Rejoignez-la à pied.');}};
}


function syncEvacuationUI(){
 const h=game.s.evacuation.haul,hold=game._haulHold,a=game.nearestEvacuee(),panel=$('evac-help'),visible=playing&&!paused&&!epilogue&&!game.s.scene&&!game.s.traversal&&(h||hold);
 panel.hidden=!visible;const field=$('playfield');field.classList.toggle('is-hauling',!!h&&playing&&!epilogue);field.classList.toggle('evac-prompt-visible',!!visible);
 const btn=document.querySelector('[data-key=haul]');btn.textContent=h?'Déposer':'Déplacer';btn.setAttribute('aria-label',h?'Déposer le compagnon sur place':'Maintenir pour déplacer le compagnon à terre');
 if(!visible){if(a&&playing&&!paused&&!epilogue&&!$('aid-help').hidden)$('aid-help').insertAdjacentHTML('beforeend','<small>Maj + I / Déplacer : dégager le blessé avant le secours.</small>');return;}
 const id=h?.id||hold?.id||a.id,name=D.companions.find(d=>d.id===id).name;
 const p=hold?Math.min(100,hold.progress/D.evacuationRules.pickupTime*100):Math.ceil(game.s.player.stamina);
 panel.innerHTML=`<span class="aid-kicker">${h?'ÉVACUATION AU SOL':hold?'PRISE EN COURS':'DÉGAGER LE BLESSÉ'}</span><b>${esc(name)} · ${h?'Traction engagée':hold?'Saisir sans le relever':'À terre'}</b><span>${h?'Marcher · I ou Déposer pour lâcher prise':hold?'Maintenir Maj + I · Le monde continue':'Maj + I / Déplacer : saisir · I seul : secourir'}</span>${h||hold?`<div class="aid-track" role="progressbar" aria-label="${hold?'Progression de la prise':'Endurance en traction'}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.floor(p)}"><i style="width:${p}%"></i></div><small>${hold?Math.floor(p)+' %':Math.ceil(p)+' % d’endurance · S’arrêter pour récupérer'}</small>`:''}`;
 // Contexts are mutually exclusive. Do not stack instructions across the character.
 $('aid-help').hidden=true;$('party-help').hidden=true;$('terrain-help').hidden=true;$('threshold-help').hidden=true;
 if(h)$('prompt').innerHTML=game.nearest()?`<kbd>E</kbd> ${esc(game.nearest().label)}`:'<kbd>Flèches</kbd> Déplacer le blessé · <kbd>I</kbd> Déposer avant de combattre ou soigner';
}
function showEvacuation(){
 if(!playing)return;const e=game.s.evacuation,h=e.haul;
 const places=D.evacuationSpots.map(s=>{const known=game.s.visited.includes(s.room),done=e.deliveries.some(v=>v.spot===s.id),route=known?game.knownRoute(s.room):[];
  return `<article class="evac-site ${done?'done':''}"><span class="eyebrow">${known?done?'DÉPOSE CONSIGNÉE':'POINT BALISÉ':'NON LOCALISÉ'}</span><h3>${known?esc(s.title):'Un point à découvrir'}</h3><p>${known?esc(s.text):'Visiter la pièce pour consigner son point de regroupement.'}</p>${known?`<p class="small">${esc(C.ROOMS.get(s.room).name)} · ${h&&!route.length?'Aucun chemin compatible avec la traction':'Rejoindre à pied'}</p><button data-evac-route="${s.room}">Marquer le trajet</button>`:''}</article>`;
 }).join('');
 const logs=e.journal.slice(-16).reverse().map(v=>`<li><time>${clock(v.at)}</time><span>${esc(D.companions.find(d=>d.id===v.id).name)} · ${{picked:'prise engagée',dropped:'déposé sur place',hurt:'prise interrompue par un coup',exhausted:'déposé à bout de forces',crossed:'seuil franchi',delivered:'point de regroupement atteint'}[v.code]} · ${esc(C.ROOMS.get(v.room).name)}</span></li>`).join('');
 openPanel('Sortir de la ligne de feu',`<p class="aid-lead">Déplacer d’abord. Secourir ensuite.</p><div class="aid-guide"><p><kbd>Maj + I</kbd> Maintenir 0,85 s pour saisir un compagnon à terre. Bouton tactile : <b>Déplacer</b>.</p><p><kbd>Flèches</kbd> Marcher lentement. <kbd>I</kbd> Déposer. Un nouvel appui maintenu sur I commence ensuite le secours gratuit.</p><p>Un coup fait lâcher prise. À l’épuisement, le blessé reste au sol à la position atteinte.</p></div><p class="muted">Les deux corps doivent passer : murs, vantaux et dalles restent bloquants. Les changements d’étage, les conduits bas et les arènes finales exigent un compagnon debout. Ni portage dans les rappels, ni ragdoll physique.</p><div class="aid-stat"><span>${e.stats.pickups} prises</span><span>${e.stats.crossings} seuils en traction</span><span>${e.deliveries.length} déposes balisées</span></div><h3>Six points de regroupement</h3><p class="muted">Ces marques ne rendent pas invulnérable et ne donnent aucun soin. Examiner la pièce ; le carnet n’affiche pas les ennemis lointains.</p><div class="evac-grid">${places}</div><h3>Interventions consignées</h3><ol class="care-log">${logs||'<li>Aucun déplacement de blessé consigné.</li>'}</ol><button id="evac-care">Blessures et haltes</button>`,'evacuation');
 $('evac-care').onclick=showRescue;
 for(const b of document.querySelectorAll('[data-evac-route]'))b.onclick=()=>{if(game.markRoute(b.dataset.evacRoute)){save();closePanel();notify('Point marqué. Aucun déplacement automatique.');}};
}

function showDeath(text){openPanel('Plus aucune trace',`<p>${esc(text)}</p><p class="muted">Reprendre au dernier passage ou à la dernière étape franchie. Les menus n’avancent pas le compte à rebours.</p><div class="button-row"><button class="primary" id="retry">Reprendre au point de passage</button><button id="dead-title">Retour à l’expédition</button></div>`,'dead');$('retry').onclick=()=>{game.retry();closePanel();caption('LEX WOODS',game.room.mood);updateHUD();save();};$('dead-title').onclick=toTitle;}
function showComplete(){save();openPanel('La marque du chasseur',`<div class="eyebrow">EXPÉDITION TERMINÉE</div><h3 class="completion-title">Sous la glace.</h3><p>La Reine disparaît dans l’eau noire. Scar ne repartira pas vivant.<br>L’Ancien reconnaît la marque de Lex et lui remet une lance.</p><div class="completion-stats"><div><strong>${game.s.visited.length}</strong><span class="small">lieux parcourus</span></div><div><strong>${game.unlockedCodex().length}</strong><span class="small">entrées du carnet</span></div><div><strong>${clock(game.s.worldTime)}</strong><span class="small">durée de l’expédition</span></div></div><div class="button-row"><button class="primary" id="see-epilogue">À bord du vaisseau</button><button id="complete-codex">Relire le carnet</button><button id="complete-title">Retour à l’expédition</button></div>`,'complete');$('see-epilogue').onclick=()=>{epilogue=true;if(!game.s.visited.includes('vessel'))game.s.visited.push('vessel');save();closePanel();caption('ÉPILOGUE','À bord du vaisseau, une forme hybride émerge du corps de Scar. La chasse a laissé une autre trace.',99999);$('objective-label').textContent='Une autre naissance';notify('Épilogue · Échap pour revenir au carnet.',6);};$('complete-codex').onclick=showCodex;$('complete-title').onclick=toTitle;}
function exportSave(){const blob=new Blob([game.serialize()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`AVP_2004_CARNET_${slot}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>512000)throw new Error('Fichier trop volumineux.');const state=C.hydrate(await f.text());game=new C.Game({state});storageConflict=false;playing=true;epilogue=false;$('shell').classList.remove('title-state');$('title').hidden=true;save();closePanel();updateHUD();caption('LEX WOODS',game.room.mood,7);notify('Carnet importé.');}catch(error){notify('Import refusé : '+error.message,7);}e.target.value='';};
$('touch-party').onclick=showParty;
$('new-game').onclick=()=>{const previous=readSave();if(previous||invalidSlot){openPanel('Ouvrir un nouveau carnet ?',`<p>La progression du carnet ${slot} sera remplacée. Les deux autres carnets restent inchangés.</p><div class="button-row"><button class="primary" id="confirm-new">Commencer une nouvelle expédition</button><button id="cancel-new">Conserver ce carnet</button></div>`,'confirm');$('confirm-new').onclick=()=>start(false);$('cancel-new').onclick=closePanel;}else start(false);};$('continue-game').onclick=()=>start(true);$('slot-select').onchange=e=>{slot=Number(e.target.value);updateSlot();};$('title-options').onclick=showOptions;$('help-button').onclick=showOptions;$('pause-button').onclick=()=>pause();$('map-button').onclick=showMap;$('codex-button').onclick=showCodex;$('close-panel').onclick=closePanel;
$('panel').addEventListener('cancel',e=>{e.preventDefault();if(!['dead','complete','confirm'].includes(menu))closePanel();});
$('game').addEventListener('contextmenu',e=>e.preventDefault());$('game').addEventListener('pointerdown',e=>{if(!playing||paused)return;audio.wake();$('game').setPointerCapture(e.pointerId);const px=renderer.point(game.s.player.x,game.s.player.y).x;game.s.player.face=e.offsetX>=px?1:-1;if(e.button===2)mouseGuard=true;else mouseAttack=true;});
function releasePointer(){mouseAttack=false;mouseGuard=false;}window.addEventListener('pointerup',releasePointer);$('game').addEventListener('pointercancel',releasePointer);
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touch.add(b.dataset.key);touchPressed.add(b.dataset.key);};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>touch.delete(b.dataset.key);}
window.addEventListener('keydown',e=>{const focused=document.activeElement;if(focused&&['INPUT','SELECT','TEXTAREA'].includes(focused.tagName))return;
 if(e.code==='Escape'){e.preventDefault();if(menu){if(!['dead','complete','confirm'].includes(menu))closePanel();}else if(playing)pause();return;}
 if(paused)return;if(!playing)return;
 if(game._talk&&!e.repeat&&['Digit1','Digit2'].includes(e.code)){e.preventDefault();game.advanceConversation(Number(e.code.slice(-1))-1);syncPartyUI();return;}
 if(game._talk&&e.code==='Tab')return;
 if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','Tab','Enter'].includes(e.code))e.preventDefault();
 if(!e.repeat){if(e.code==='KeyY'){showCrossings();return;}if(e.code==='KeyO'){showParty();return;}if(e.code==='KeyK'){showTerrain();return;}if(e.code==='KeyB'){showInvestigations();return;}if(e.code==='KeyM'){showMap();return;}if(e.code==='KeyP'){showOperations();return;}if(e.code==='KeyN'){showLocalMap();return;}if(e.code==='Tab'){showCodex();return;}if(e.code==='F6'){e.preventDefault();game.setMode(game.s.mode==='classic'?'hybrid':'classic');settings.mode=game.s.mode;persistSettings();save();return;}}
 keys.add(e.code);if(!e.repeat)pressed.add(e.code);audio.wake();});window.addEventListener('keyup',e=>keys.delete(e.code));
function input(){const has=(...codes)=>codes.some(c=>keys.has(c)||pressed.has(c)),t=k=>touch.has(k)||touchPressed.has(k);return {dx:(has('KeyD','ArrowRight')||t('right')?1:0)-(has('KeyA','ArrowLeft')||t('left')?1:0),dy:(has('KeyS','ArrowDown')||t('down')?1:0)-(has('KeyW','ArrowUp')||t('up')?1:0),run:has('ShiftLeft','ShiftRight')||t('run'),crouch:has('KeyC')||t('crouch'),guard:mouseGuard||has('KeyR')||t('guard'),attack:mouseAttack||has('KeyJ')||t('attack'),dodge:has('Space')||t('dodge'),interact:has('KeyE','Enter')||t('interact'),flare:has('KeyF')||t('flare'),heal:has('KeyH')||t('heal'),order:has('KeyG')||t('order'),lamp:has('KeyL')||t('lamp'),seal:has('KeyV')||t('seal'),listen:has('KeyX')||t('listen'),utility:has('KeyT')||t('utility'),talk:has('KeyU')||t('talk'),aid:has('KeyI')||t('aid'),haul:(has('ShiftLeft','ShiftRight')&&has('KeyI'))||t('haul')};}
window.addEventListener('blur',()=>{clearInputs();if(playing&&!paused&&!game.dead&&!game.s.completed)pause('La fenêtre a perdu le focus.');});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInputs();if(playing&&!paused&&!game.dead&&!game.s.completed)pause('L’expédition est en pause.');}});
window.addEventListener('pagehide',()=>{if(!leavingHost)save();});window.addEventListener('pageshow',e=>{if(e.persisted&&leavingHost){leavingHost=false;if(playing&&!game.dead)pause();else paused=false;}});window.addEventListener('storage',e=>{if(e.key===keyFor()&&playing){storageConflict=true;pause('Une autre fenêtre a modifié ce carnet. La sauvegarde automatique est arrêtée pour ne pas l’écraser.');}});
if(hosted){$('host-return').hidden=false;$('host-return').onclick=e=>{e.preventDefault();returnToHost();};}
let hudClock=0,footClock=0;
function frame(now){const dt=lastTime?Math.min((now-lastTime)/1000,.05):0;lastTime=now;if(playing&&!paused&&!document.hidden){game.tick(dt,input());pressed.clear();touchPressed.clear();autosave+=dt;footClock+=dt;if(autosave>3){save();autosave=0;}if(game.moving&&footClock>.36){audio.play('foot');footClock=0;}}
 for(const ev of game.drain()){
  audio.play(ev.type);if(ev.type==='bark'){caption(ev.speaker,ev.text,7);}else if(ev.type==='companion-hurt'){notify(ev.text,2.2);}else if(ev.type==='party'){notify(ev.text,3.5);}else if(ev.type==='conversation'){syncPartyUI();}else if(ev.type==='field'){caption(ev.title,ev.text,8);updateHUD();}else if(ev.type==='balance')showBalance();else if(ev.type==='operation'){caption(ev.title,ev.text,7);updateHUD();}else if(ev.type==='cinematic'){caption('LEX WOODS',ev.text,9);}else if(ev.type==='puzzle')showSeal();else if(ev.type==='save')save();else if(ev.type==='room'){caption('LEX WOODS',game.room.mood,6);updateHUD();}else if(ev.type==='chapter'){caption(ev.speaker,ev.line+' '+ev.text,10);notify(`Étape ${ev.number} terminée`,2.2);updateHUD();}else if(ev.type==='log'){caption(ev.title,ev.text,10);}else if(['terrain','piton','piton-hit','hunt','door-hit','door-move'].includes(ev.type))notify(ev.text);else if(ev.type==='notice'||ev.type==='mode'||ev.type==='cycle'||ev.type==='warning')notify(ev.text);else if(ev.type==='dead')showDeath(ev.text);else if(ev.type==='complete')showComplete();
 }
 if(!paused){noticeTime-=dt;captionTime-=dt;}if(noticeTime<=0)$('notice').hidden=true;
 if(captionTime<=0&&playing&&!epilogue){$('speaker').textContent='EN COURS';$('narration-text').textContent=game.guide?`${game.guide.title} — ${C.ROOMS.get(game.guide.room).name}`:'La marque du chasseur.';}
 renderer.draw(game,{title:!playing,epilogue});syncEncounterUI();hudClock+=dt;if(hudClock>.12){if(!epilogue)updateHUD();hudClock=0;}requestAnimationFrame(frame);
}
renderer.ready.then(()=>{updateSlot();requestAnimationFrame(frame);});
